// [2026-11-02 14:12 | page-size-unlock] directDiscard, directStore, directSkeleton: delete, move (as a stream) and scan the staged page.
async function directDiscard(env, direct) { try { if (direct) await env.NOTES_BUCKET.delete(direct.key); } catch (e) { /* the nightly clean-up gets it */ } }
