// [2026-11-02 15:05 | page-space-balance] Settles the hold once the page is stored: takes the space if the balance still covers it (one statement, so two saves can't overdraw), gives back what a smaller page no longer needs.
async function pageSizeCommit(env, spend, slug) {
  if (!spend || !spend.sub) return;
  try {
    await ensurePageSizeCredits(env);
    const need = pageExtraMb(spend.bytes), held = await pageSpaceHeldMb(env, spend.sub, slug), now = Date.now();
    if (need > held) {
      const d = need - held;
      const r = await env.ADS_DB.prepare("INSERT INTO page_space_ledger (owner_sub, delta, reason, slug, created_at) SELECT ?, ?, 'hold', ?, ? WHERE (SELECT COALESCE(SUM(delta), 0) FROM page_space_ledger WHERE owner_sub = ?) >= ?")
        .bind(spend.sub, -d, slug, now, spend.sub, d).run();
      if (!(r && r.meta && r.meta.changes)) console.log('page space hold lost a race for ' + slug + ' (' + d + ' MB)'); // the page is stored; the balance changed in between
    } else if (need < held) {
      await env.ADS_DB.prepare("INSERT INTO page_space_ledger (owner_sub, delta, reason, slug, created_at) VALUES (?, ?, 'release', ?, ?)").bind(spend.sub, held - need, slug, now).run();
    }
  } catch (e) { console.log('page size commit failed: ' + (e && e.message)); }
}
