  await env.ADS_DB.prepare('INSERT INTO team_messages (id, slug, sender_sub, kind, body, reply_to, created_at, version, deleted) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0)').bind(id, slug, sub, kind, body, replyTo || null, now, version || null).run();
