    env.ADS_DB.prepare('SELECT m.slug AS slug, COUNT(*) AS c FROM team_messages m LEFT JOIN team_chat_reads r ON r.slug = m.slug AND r.member_sub = ? WHERE m.slug IN (' + ph + ') AND m.sender_sub != ? AND m.deleted = 0 AND m.created_at > COALESCE(r.read_at, 0) GROUP BY m.slug').bind(sub, ...slugs, sub).all(),
    env.ADS_DB.batch(slugs.map((sl) => env.ADS_DB.prepare('SELECT id, slug, sender_sub, kind, body, created_at FROM team_messages WHERE slug = ? AND deleted = 0 ORDER BY created_at DESC, rowid DESC LIMIT 1').bind(sl))),
    env.ADS_DB.prepare("SELECT slug, COUNT(*) AS c FROM team_members WHERE slug IN (" + ph + ") AND status = 'active' GROUP BY slug").bind(...slugs).all()
