      const emoji = b && b.emoji;
      if (typeof emoji !== 'string' || !TEAM_CHAT_REACTIONS.includes(emoji)) return textError(400, 'That reaction isn\u2019t available.');
      if (!row || row.deleted) return textError(404, 'That message is gone.');
      const have = await env.ADS_DB.prepare('SELECT emoji FROM team_reactions WHERE message_id = ? AND member_sub = ?').bind(id, sub).first();
      // Optional explicit `on` (newer apps): true sets, false clears, so a retry or a stale copy can never flip the reaction back. Without it (older apps) the call still toggles.
