        slug: r.slug,
        title: r.title,
        authorSub: idBySub[r.author_sub], // opaque author ID (field name kept for older app builds)
        authorProfileName: nameBySub[r.author_sub],
        verified: verifiedBy.get(r.slug) === r.author_sub ? true : undefined, // [2026-11-01 07:23 | verified-names] this page is on the verified name
        // [2026-11-02 22:02 | verified-cards] changed: verifiedProfile = the author holds a verified name but this page is not on it (the app draws a different tick)
        verifiedProfile: (verifiedAuth.has(r.author_sub) && verifiedBy.get(r.slug) !== r.author_sub) ? true : undefined,
        createdAt: r.created_at, // when it became a story (drives feed order)
        noteCreatedAt: r.note_created_at || null, // when the note itself was created (what the card's time-ago shows)
        desc: r.description || '',
        tags: parseStoryTags(r.tags),
        seen: !!r.seen,
        images: card.images,
        imageCount: card.count, // total images in the note, for the "+N" badge
