// [2026-11-03 ??:?? | discoverable-setting] The app's onboarding carousel photos (the four under the empty Library), cut to 720x405 JPEG so the not-found screen stays light. Served at /nb-onboard/1.jpg to 4.jpg (handleOnboardImg), cached for a year.
const NB_ONBOARD_IMGS = ["", "", "", ""];
const NB_ONBOARD_CAPS = ["Embed Instagram posts and YouTube videos, turn a note to a website.", "Sign in once, and your notes follow you to every device for free.", "Add different components and put everything in perspective.", "Nobody has to know, share with the world or save it for you and yours."]; // same words as the app's carousel (#nb-onboard-carousel)
let nbOnboardBytes = null;
function handleOnboardImg(name) {
  const m = /^([1-4])\.jpg$/.exec(name || '');
  if (!m) return new Response('Not found', { status: 404, headers: corsHeaders() });
  if (!nbOnboardBytes) nbOnboardBytes = NB_ONBOARD_IMGS.map(b => Uint8Array.from(atob(b), c => c.charCodeAt(0)));
  return new Response(nbOnboardBytes[Number(m[1]) - 1], { headers: { 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=31536000, immutable', 'X-Content-Type-Options': 'nosniff', ...corsHeaders() } });
}

