  dots:svg('<circle cx="6.5" cy="12" r="1.3"/><circle cx="12" cy="12" r="1.3"/><circle cx="17.5" cy="12" r="1.3"/>'),
  reports:svg('<path d="M6 20V4"/><path d="M6 4.5h11.5L15 8.5l2.5 4H6"/>'),
