function lgDefaultMsg(kind){return 'We updated our '+LG_LBL[kind]+'. You can read it any time from your account screen in the app.'}
function lgEdit(kind,d,keep){
  var wrap=el('div'),ta=el('textarea','field ta'),tabs=el('div','lge-tabs'),panes={},tabBtns={},cur='';
  var base=keep&&keep.base!=null?keep.base:(LG.base[kind]!=null?LG.base[kind]:d.version),warn=el('div');
  ta.rows=14;ta.spellcheck=false;ta.autocomplete='off';ta.setAttribute('autocapitalize','off');ta.setAttribute('aria-label',LG_LBL[kind]+' text');
  ta.style.cssText='font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px;line-height:1.5';
  ta.value=keep?keep.text:(LG.draft[kind]||d.html);
  tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Edit sections');
  var pvBox=el('div');
  var tg=el('label','tog'),tt=el('span','tog-text'),cb=document.createElement('input');
  tt.appendChild(el('b',null,'Alert signed-in accounts'));tt.appendChild(el('small',null,'Every signed-in account gets an alert about the change. Everyone, signed in or not, sees the new text the next time the app shows it.'));
  cb.type='checkbox';cb.checked=keep?keep.notify:true;tg.appendChild(tt);tg.appendChild(cb);
  var ma=el('textarea','field ta');ma.rows=4;ma.maxLength=250;ma.setAttribute('aria-label','Alert message');ma.value=keep?keep.message:lgDefaultMsg(kind);
  var pos=keep&&keep.pos||{text:{box:0,body:0},preview:{box:0,body:0},alert:{box:0,body:0}};
  function sync(){
    if(cb.checked){ma.hidden=false;ma.scrollTop=pos.alert.box}
    else{if(!ma.hidden)pos.alert.box=ma.scrollTop;ma.hidden=true}
    tabBtns.alert.textContent='Alert: '+(cb.checked?'on':'off');
    fit()
  }
  var hint=el('div','fine','Plain markup only: h3 headings, p, ul and li, strong, em and links. Anything else is stripped in the app. The Effective date at the top is set to the publish date when you publish.');hint.style.margin='0 0 8px';
  function warnSync(){
    warn.textContent='';
    if(LG.from[kind]!=null){var rf=el('div','fine','Restored from '+(LG.from[kind]?'version '+LG.from[kind]:'the built-in copy')+'.');rf.style.margin='8px 0 0';warn.appendChild(rf)}
    if(base===d.version)return;
    var wn=el('div','fine','This draft started from version '+base+', but version '+d.version+' is live now, so it cannot be published as it is. Tap Use live text and redo your edits (or paste them in).');wn.style.margin='8px 0 0';wn.style.color='var(--danger)';warn.appendChild(wn);
    var ub=btn('Use live text','quiet',function(){ta.value=d.html;base=d.version;delete LG.from[kind];warnSync()});ub.style.marginTop='8px';warn.appendChild(ub)
  }
  warnSync();
  var P={text:[ta,warn],preview:[pvBox],alert:[tg,ma]};
  [['text','Text'],['preview','Preview'],['alert','Alert']].forEach(function(t){
    var b=document.createElement('button');b.type='button';b.className='lge-tab';b.id='lge-t-'+t[0];b.textContent=t[1];
    b.setAttribute('role','tab');b.setAttribute('aria-controls','lge-p-'+t[0]);
    b.onclick=function(){pick(t[0])};
    tabs.appendChild(b);tabBtns[t[0]]=b;
    var pn=el('div','lge-pane');pn.id='lge-p-'+t[0];pn.setAttribute('role','tabpanel');pn.setAttribute('aria-labelledby',b.id);
    P[t[0]].forEach(function(n){pn.appendChild(n)});
    panes[t[0]]=pn;pn.hidden=true;wrap.appendChild(pn)
  });
  tabs.addEventListener('keydown',function(e){
    var k=['text','preview','alert'],i=k.indexOf(cur),n=e.key==='ArrowRight'?i+1:e.key==='ArrowLeft'?i-1:-1;
    if(n<0)return;e.preventDefault();n=(n+k.length)%k.length;pick(k[n]);tabBtns[k[n]].focus()
  });
  function frWin(){var f=pvBox.firstChild;try{return f&&f.contentWindow}catch(e){return null}}
  // Starts each textarea no taller than the visible part of the sheet, so its resize handle is in view. The room is worked out from
  // the sheet's own size limit, not from how tall it is now. Once someone drags a handle that box keeps their height: the dialog
  // grows with it (up to its limit, then scrolls), and only on that tab, because every tab's box holds its own height.
  function fit(){
    var sb=wrap.closest('.sheet-body'),sh=sb&&sb.closest('.sheet');if(!sb||!sh)return;
    var maxSb=window.innerHeight*0.88-(sh.offsetHeight-sb.clientHeight);
    [ta,ma].forEach(function(t){
      if(t.hidden||!t.offsetParent)return;
      var top=t.getBoundingClientRect().top-sb.getBoundingClientRect().top+sb.scrollTop;
      if(t._user)return;
      var room=Math.max(48,Math.floor(maxSb-top-8));
      t.style.maxHeight='none';t.style.minHeight=Math.min(116,room)+'px';t.style.height='';
      t._fitH=Math.min(t.offsetHeight,room);t.style.height=t._fitH+'px'
    })
  }
  var ro=window.ResizeObserver?new ResizeObserver(function(es){es.forEach(function(e){var t=e.target;if(t.offsetParent&&t._fitH!=null&&Math.abs(t.offsetHeight-t._fitH)>1)t._user=true})}):null;
  if(ro){ro.observe(ta);ro.observe(ma)}
  function savePos(){
    if(!cur)return;var o=pos[cur],w,sb0=wrap.closest('.sheet-body');if(sb0)o.body=sb0.scrollTop;
    if(cur==='preview'){w=frWin();try{if(w)o.box=w.pageYOffset}catch(e){}}
    else if(cur==='text')o.box=ta.scrollTop;
    else if(cur==='alert'&&!ma.hidden)o.box=ma.scrollTop
  }
  function applyPos(name){
    var o=pos[name];
    if(name==='text')ta.scrollTop=o.box;else if(name==='alert'&&!ma.hidden)ma.scrollTop=o.box;
    var sb1=wrap.closest('.sheet-body');if(sb1)sb1.scrollTop=o.body||0
  }
  function pick(name){
    if(name===cur)return;
    savePos();cur=name;
    Object.keys(panes).forEach(function(k){var on=k===name;panes[k].hidden=!on;tabBtns[k].setAttribute('aria-selected',on?'true':'false');tabBtns[k].tabIndex=on?0:-1});
    hint.hidden=name!=='text';
    if(name==='preview'){
      pvBox.textContent='';var fr=lgFrame(ta.value),y=pos.preview.box;
      fr.setAttribute('sandbox','allow-same-origin');
      fr.style.height='max(180px,calc(88vh - 270px))';fr.style.height='max(180px,calc(88dvh - 270px))';
      // Hold the frame hidden until its scroll is restored, so it never shows at the top first.
      var shown=false,reveal=function(){if(!shown){shown=true;fr.style.visibility=''}};
      if(y>0){fr.style.visibility='hidden';setTimeout(reveal,600)}
      fr.addEventListener('load',function(){try{fr.contentWindow.scrollTo(0,y)}catch(e){}reveal()});
      pvBox.appendChild(fr)
    }
    fit();
    applyPos(name)
  }
  cb.onchange=sync;sync();pick(keep&&keep.tab||'text');
  // The markup note sits in the pinned header with the tabs, so it never scrolls out of view while the Text tab is open.
  var hdr=el('div');hdr.appendChild(tabs);hdr.appendChild(hint);
  var pr=ask({title:'Edit '+LG_LBL[kind],sev:'other',icon:'shield',ok:'Publish',text:d.builtin?'Starting from the copy built into the app.':'Starting from version '+d.version+'.',head:hdr,node:wrap});
  fit();applyPos(cur);window.addEventListener('resize',fit);
  return pr.then(function(ok){
    window.removeEventListener('resize',fit);if(ro)ro.disconnect();
    if(!ok){if(ta.value.trim()!==(d.html||'').trim()){LG.draft[kind]=ta.value;LG.base[kind]=base}else{delete LG.draft[kind];delete LG.base[kind];delete LG.from[kind]}return}
    savePos();
    var st={text:ta.value.trim(),notify:cb.checked,message:ma.value.trim(),tab:cur,pos:pos,base:base};
    if(!st.text){msg('The text cannot be empty','err');return lgEdit(kind,d,st)}
    if(lgBody(st.text)===lgBody(d.html)){msg('Nothing has changed','err');return lgEdit(kind,d,st)}
    if(st.notify&&!st.message){msg('Write the alert, or turn it off','err');st.tab='alert';return lgEdit(kind,d,st)}
    var go=function(){
      return api('/admin/legal',{method:'POST',body:{kind:kind,base:base,from:LG.from[kind],html:st.text,notify:st.notify,message:st.message}}).then(function(o){
        if(o.s===409){
          LG.draft[kind]=st.text;LG.base[kind]=base;LG.data[kind]=null;
          msg('Someone published version '+((o.j&&o.j.current)||'')+' first, so nothing was changed. Your text is kept as a draft: open Edit to review it.','err');
          return lgLoad(true)
        }
        if(!o.ok){showErr(o,'Could not publish the '+LG_LBL[kind]);return lgEdit(kind,d,st)}
        delete LG.draft[kind];delete LG.base[kind];delete LG.from[kind];LG.data[kind]=null;
        msg('Published '+LG_LBL[kind]+' version '+o.j.version+(st.notify?(o.j.alertFailed?', but the alert could not be sent':', alert sent to '+pl(o.j.sent,'signed-in account')):''));
        if(st.notify&&o.j.alertFailed){return lgLoad(true).then(function(){return ask({title:'Alert not sent',sev:'ad',icon:'bell',text:'The new text is live, but the alert could not be sent. Send it again?',ok:'Send alert'})}).then(function(y){if(y)return lgResend(kind,o.j.version)})}
        return lgLoad(true)
      })
    };
    var cs=lgDiffNode(d.html,st.text)._st,sum=' ('+cs.add+(cs.add===1?' line':' lines')+' added, '+cs.del+' removed, version '+d.version+' to '+(d.version+1)+')';
    if(!st.notify)return ask({title:'Publish without an alert?',sev:'ad',icon:'shield',text:'This puts the new '+LG_LBL[kind]+' live for everyone'+sum+' with no alert. People see it the next time the app shows it.',ok:'Publish'}).then(function(y){return y?go():lgEdit(kind,d,st)});
    return ask({title:'Alert signed-in accounts?',sev:'ad',icon:'bell',text:'This publishes the new '+LG_LBL[kind]+sum+' and sends every signed-in account this alert: '+st.message,ok:'Publish and alert'}).then(function(y){return y?go():lgEdit(kind,d,st)})
  })
}
