function ovQuietPaged(){
  if(ovS.qb)return Promise.resolve();
  var users=ovS.view==='users',g=ovS.gen,want=ovS.shown,rows=[],tot=null,cu='',pg=0,first=null,view=ovS.view,same=false,deep=Date.now()-(FRESH.ovD||0)>60000;
  var base='&q='+encodeURIComponent(ovS.q)+'&sort='+(users?ovS.sort+'&f='+ovS.fil:ovS.nsort)+ovPerQs(users);
  ovS.qb=true;
  function step(){
    return api('/admin/'+view+'?cursor='+encodeURIComponent(cu)+base).then(function(o){
      if(g!==ovS.gen)return null;
      if(!o.ok){if(o.s===403)bad(o,'Could not load the list');else qfail('ov',o);return null}
      if(first===null){first=view+JSON.stringify(o.j);same=first===SIG.ovl;if(same&&!deep)return null}
      rows=rows.concat(users?o.j.users:o.j.notes);if(o.j.total!=null)tot=o.j.total;cu=o.j.next;
      if(cu!=null&&rows.length<want&&++pg<20)return step();
      return{next:cu}
    })
  }
  return step().then(function(r){
    ovS.qb=false;if(!r||g!==ovS.gen||view!==ovS.view)return;
    var full=view+JSON.stringify(rows);if(deep)FRESH.ovD=Date.now();if(same&&full===SIG.ovlF)return;
    var L=$('ovlist'),m=$('ovmore'),y=window.pageYOffset;SIG.ovl=first;SIG.ovlF=full;L.textContent='';
    rows.forEach(users?ovUser:ovNote);
    ovS.cur=r.next;if(tot!=null)ovS.total=tot;ovS.shown=rows.length;m.hidden=ovS.cur==null;
    $('ovcount').textContent=ovS.total?'Showing '+num(ovS.shown)+' of '+num(ovS.total):'';
    if(!L.firstChild)L.appendChild(empty(users?'No users':'No notes','Nothing matches this search.',users?'users':'reports'));
    window.scrollTo(0,y)
  }).catch(function(){ovS.qb=false;delete FRESH.ov})
}
function ovList(reset,quiet){
  var L=$('ovlist'),m=$('ovmore'),users=ovS.view==='users',g=quiet?ovS.gen:++ovS.gen;
  if(quiet&&ovS.paged)return ovQuietPaged();
  if(quiet){}
  else if(reset){
    ovS.paged=false;SIG.ovl='';SIG.ovlF='';ovSnap(users);ovS.cur='';ovS.total=0;ovS.shown=0;L.textContent='';moreBusy(m,false);m.hidden=true;$('ovcount').textContent='';
    skel(L,4,'row')
  }
  else{ovS.paged=true;SIG.ovlF='';moreBusy(m,true)}
  var qs='cursor='+encodeURIComponent(quiet?'':ovS.cur)+'&q='+encodeURIComponent(ovS.q)+'&sort='+(users?ovS.sort+'&f='+ovS.fil:ovS.nsort)+ovPerQs(users);
  return api('/admin/'+ovS.view+'?'+qs).then(function(o){
    if(g!==ovS.gen)return;
    var y=window.pageYOffset;
    if(quiet){
      if(!o.ok){if(o.s===403)bad(o,'Could not load the list');else qfail('ov',o);return}
      var sg=ovS.view+JSON.stringify(o.j);if(sg===SIG.ovl)return;
      SIG.ovl=sg;L.textContent='';ovS.shown=0
    }else{
      unskel(L);moreBusy(m,false);
      if(!o.ok){bad(o,'Could not load the list');return}
      if(reset)SIG.ovl=ovS.view+JSON.stringify(o.j)
    }
    var rows=users?o.j.users:o.j.notes;
    rows.forEach(users?ovUser:ovNote);
    ovS.cur=o.j.next;if(o.j.total!=null)ovS.total=o.j.total;ovS.shown+=rows.length;
    m.hidden=ovS.cur==null;
    $('ovcount').textContent=ovS.total?'Showing '+num(ovS.shown)+' of '+num(ovS.total):'';
    if(!L.firstChild)L.appendChild(empty(users?'No users':'No notes','Nothing matches this search.',users?'users':'reports'));
    if(quiet)window.scrollTo(0,y)
  }).catch(function(e){if(quiet){if(g===ovS.gen)delete FRESH.ov;return}if(g!==ovS.gen)return;unskel(L);moreBusy(m,false);netFail(e)})
}

/* ---------- Trends: growth and decline over time ---------- */
var trWIN={day:30,week:12,month:12,year:5},trOPT={day:[7,14,30,90],week:[4,8,12,26],month:[3,6,12,24],year:[2,3,5,10]},trMINV='30 Sep 2026',trUNIT={day:'days',week:'weeks',month:'months',year:'years'},trOFF=tzOff(Date.now()),trMIN=Date.UTC(2015,0,1);
var trRL={csam:'Child safety',abuse:'Abuse',copyright:'Copyright',spam:'Spam',other:'Other'},trRO=['csam','abuse','copyright','spam','other'],trRC={csam:'#FF4D6D',abuse:'#FF9A5C',copyright:'#F7C35B',spam:'#97A3F0',other:'#46D6C8'};
